class ApproxLfuCache {
    private final LinkedHashMap<String, String> data = new LinkedHashMap<>(16, 0.75f, true);
    private final Map<String, Integer> accessCount = new HashMap<>();
    private final int capacity;

    ApproxLfuCache(int capacity) { this.capacity = capacity; }

    void put(String key, String value) {
        data.put(key, value);
        accessCount.merge(key, 1, Integer::sum);
        if (data.size() > capacity) {
            String leastFrequent = data.keySet().stream()
                    .min(Comparator.comparingInt(k -> accessCount.getOrDefault(k, 0)))
                    .orElse(null);
            if (leastFrequent != null) {
                data.remove(leastFrequent);
                accessCount.remove(leastFrequent);
            }
        }
    }

    String get(String key) {
        accessCount.merge(key, 1, Integer::sum);
        return data.get(key);
    }
}

