class SessionTracker {
    private final LinkedHashMap<String, Long> sessions = new LinkedHashMap<>(16, 0.75f, true);

    void touch(String userId) {
        sessions.put(userId, System.currentTimeMillis());
    }

    void expireOld(int maxSessions) {
        Iterator<String> it = sessions.keySet().iterator();
        while (sessions.size() > maxSessions && it.hasNext()) {
            it.next();
            it.remove();
        }
    }
}

