static final LinkedHashMap<Integer, Long> memo = new LinkedHashMap<>(16, 0.75f, true) {
    @Override
    protected boolean removeEldestEntry(Map.Entry<Integer, Long> eldest) { return size() > 5; }
};

static long factorial(int n) {
    if (memo.containsKey(n)) return memo.get(n);
    long result = (n <= 1) ? 1 : n * factorial(n - 1);
    memo.put(n, result);
    return result;
}

public static void main(String[] args) {
    for (int n : new int[]{5, 3, 7, 5, 4}) {
        System.out.println("silnia(" + n + ") = " + factorial(n) + ", cache: " + memo.keySet());
    }
}

