Map<Integer, List<Integer>> graph = Map.of(
    1, List.of(2, 3), 2, List.of(1, 4), 3, List.of(1), 4, List.of(2)
);
int start = 1;

LinkedHashMap<Integer, Integer> distances = new LinkedHashMap<>();
Queue<Integer> queue = new LinkedList<>();
queue.add(start);
distances.put(start, 0);

while (!queue.isEmpty()) {
    int node = queue.poll();
    int dist = distances.get(node);
    for (int neighbor : graph.getOrDefault(node, List.of())) {
        if (!distances.containsKey(neighbor)) {
            distances.put(neighbor, dist + 1);
            queue.add(neighbor);
        }
    }
}
System.out.println("Kolejnosc BFS z odlegloscia: " + distances);

